            // result: [pos+2..n-1, pos+1, 0..pos] -> element at pos is now at position n-1
            if(pos < n-2 && pos+1 > 0 && n-2-pos > 0){
                doOp(pos+1, n-2-pos);
            } else if(pos == n-2){
                // x=1, y=1: swap first and last around middle
                // result: [p[n-1], p[1..n-2], p[0]]. Element at n-2 stays at n-2, not n-1.
                // Use x=n-1, y... nah. x=pos+1=n-1, y must be >0 and x+y<n so y<1. Invalid.
                // Just swap last two: x=1,y=1 -> [p[n-1],p[1..n-2],p[0]]. pos=n-2 -> still n-2. Hmm.
                doOp(n-2, 1); // [p[n-1], p[n-2], p[0..n-3]] -> element at n-2 is now at pos 1... 
                pos = 1; // redo
                if(pos != n-1) doOp(pos+1, n-2-pos);
            }
            pos = n-1;
        }
        // Step 2: move from n-1 to target
        if(target < n-1 && n-1-target > 0 && target+1 < n){
            // x=n-1-target, y=1: result=[p[n-1], p[n-1-target..n-2], p[0..n-2-target]]
            // element at position 0 -> need it at target
            // x=target, y=n-target-1... nah. Let me use x=1,y=n-1-target
            doOp(1, n-1-target);
            // result: [p[target..n-1], p[1..target-1], p[0]] -> p[n-1] is at position n-1-target... 
            // Actually p[target..n-1] has n-target elements, element at n-1 is at index n-1-target in this block = position n-1-target
            // That's not target either. Let me just brute force check.
        }
    }

    bool sorted=true;
    for(int i=0;i<n;i++) if(p[i]!=i+1) sorted=false;
    if(!sorted){printf("0\n");return 0;}
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
